float shadow(vec3 pt) {
vec3 lightDir = normalize(lightPos - pt);
float kd = 1;
int step = 0;
for (float t = 0.1;
t < length(lightPos - pt)
&& step < renderDepth && kd > 0.001; ) {
float d = abs(getSDF(pt + t \* lightDir));
if (d < 0.001) {
kd = 0;
} else {
kd = min(kd, 16 \* d / t);
}
t += d;
By dividing d by t, we
step++;
attenuate the strength
}
